import { FastifyInstance } from 'fastify'; export async function editorRoutes(app: FastifyInstance){ app.get('/articles', async()=>({items:[]})); app.post('/articles/:article_id/rc', async()=>({rc_id:'rc_demo'})); app.get('/articles/:article_id/rc', async()=>({rc_id:'rc_demo',mapping:[]})); app.post('/rc/:rc_id/approve', async()=>({ok:true})); app.post('/rc/:rc_id/publish', async()=>({ok:true})); app.get('/rc/:rc_id/export.docx', async (req,reply)=>{ reply.header('content-type','application/vnd.openxmlformats-officedocument.wordprocessingml.document'); return 'DOCX_PLACEHOLDER'; }); }
